141	func fetchAndMergeSessionsCommon(ctx context.Context, target, branchName string) error {
142		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
143		defer cancel()
144	
145		// Determine fetch refspec. When target is a URL, use a temp ref;
146		// when it's a remote name, use the standard remote-tracking ref.
147		var fetchedRefName plumbing.ReferenceName
148		var refSpec string
149		if isURL(target) {
150			tmpRef := "refs/entire-fetch-tmp/" + branchName
151			refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
152			fetchedRefName = plumbing.ReferenceName(tmpRef)
153		} else {
154			refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
155			fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
156		}
157	
158		// Use git CLI for fetch (go-git's fetch can be tricky with auth).
159		// Use --filter=blob:none for a partial fetch that downloads only commits
160		// and trees, skipping blobs. The merge only needs the tree structure to
161		// combine entries; blobs are already local or fetched on demand.
162		fetchCmd := CheckpointGitCommand(ctx, target, "fetch", "--no-tags", "--filter=blob:none", target, refSpec)
