200	// detectRemoteOnlyArchives discovers archived generation refs on the remote
201	// that don't exist locally. Returns them sorted ascending (oldest first).
202	func detectRemoteOnlyArchives(ctx context.Context, target string, repo *git.Repository) ([]string, error) {
203		ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
204		defer cancel()
205	
206		cmd := CheckpointGitCommand(ctx, target, "ls-remote", target, paths.V2FullRefPrefix+"*")
207		cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")
208		output, err := cmd.Output()
209		if err != nil {
210			return nil, fmt.Errorf("ls-remote failed: %w", err)
211		}
212	
213		var remoteOnly []string
214		for _, line := range strings.Split(strings.TrimSpace(string(output)), "\n") {
215			if line == "" {
216				continue
217			}
218			parts := strings.Fields(line)
219			if len(parts) < 2 {
220				continue
221			}
222			refName := parts[1]
223			suffix := strings.TrimPrefix(refName, paths.V2FullRefPrefix)
224			if suffix == "current" || !checkpoint.GenerationRefPattern.MatchString(suffix) {
225				continue
226			}
227			// Only check for existence, not hash equality. A locally-present archive
228			// could be stale if another machine updated it via rotation conflict recovery,
229			// but that's unlikely and the checkpoints are still on /main regardless.
230			if _, err := repo.Reference(plumbing.ReferenceName(refName), true); err != nil {
231				remoteOnly = append(remoteOnly, suffix)
232			}
233		}
234	
235		sort.Strings(remoteOnly)
236		return remoteOnly, nil
237	}
