239	// handleRotationConflict handles the case where remote /full/current was rotated.
240	// Merges local /full/current into the latest remote archived generation to avoid
241	// duplicating checkpoint data, then adopts remote's /full/current as local.
242	func handleRotationConflict(ctx context.Context, target string, repo *git.Repository, refName, tmpRefName plumbing.ReferenceName, remoteOnlyArchives []string) error {
243		// Use the latest remote-only archive
244		latestArchive := remoteOnlyArchives[len(remoteOnlyArchives)-1]
245		archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + latestArchive)
246	
247		// Fetch the latest archived generation
248		archiveTmpRef := plumbing.ReferenceName("refs/entire-fetch-tmp/archive-" + latestArchive)
249		archiveRefSpec := fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef)
250		fetchCmd := CheckpointGitCommand(ctx, target, "fetch", "--no-tags", "--filter=blob:none", target, archiveRefSpec)
251		fetchCmd.Env = append(fetchCmd.Env, "GIT_TERMINAL_PROMPT=0")
252		if output, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
253			return fmt.Errorf("fetch archived generation failed: %s", output)
254		}
255		defer func() {
256			_ = repo.Storer.RemoveReference(archiveTmpRef) //nolint:errcheck // cleanup is best-effort
257		}()
